#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="D:\new_project\mizuki\node_modules\.pnpm\microbundle@0.15.1_rolldown@1.1.5\node_modules\microbundle\node_modules;D:\new_project\mizuki\node_modules\.pnpm\microbundle@0.15.1_rolldown@1.1.5\node_modules;D:\new_project\mizuki\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/d/new_project/mizuki/node_modules/.pnpm/microbundle@0.15.1_rolldown@1.1.5/node_modules/microbundle/node_modules:/mnt/d/new_project/mizuki/node_modules/.pnpm/microbundle@0.15.1_rolldown@1.1.5/node_modules:/mnt/d/new_project/mizuki/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../microbundle/dist/cli.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../microbundle/dist/cli.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../microbundle/dist/cli.js" $args
  } else {
    & "node$exe"  "$basedir/../microbundle/dist/cli.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
